\label{thm:main-non-vanishing}
Let $\ell\in\{3,4,6\}$, and fix an odd prime power
$q\equiv-1\pmod\ell$. For the family \eqref{intro:family},
\begin{equation}\label{intro:non-vanishing}
 \liminf_{\substack{g\to\infty\\\ell-1\mid g}}
 \frac{\#\{\chi\in\mathcal C_\ell(g):L_q(1/2,\chi)\ne0\}}
      {|\mathcal C_\ell(g)|}
 \ge\frac{A_{\ell,q,G}}{2 e^{e^{65}+3}}
 \ge\frac{1}{2 e^{e^{65}+3}}
 > e^{-e^{66}}.
\end{equation}

\label{lem:count}
For every $\varepsilon>0$,
\begin{equation}\label{eq:count}
 |\mathcal C_4(g)|=c_q q^{2m}+O_{q,\varepsilon}(q^{(1+\varepsilon)m}),
\end{equation}
where
\begin{equation}\label{eq:cq}
 c_q=
 \prod_{\deg P\ \text{odd}}(1-|P|^{-2})
 \prod_{\deg P\ \text{even}}
 (1+2|P|^{-1})(1-|P|^{-1})^2>0.
\end{equation}
Moreover,
\begin{equation}\label{eq:cq-lower}
 c_q\ge\zeta_q(2)^{-3}=(1-q^{-1})^3.
\end{equation}

\label{lem:orthog}
Let $A,B\in\mathcal A_q$ be monic and suppose
$\deg\operatorname{rad}(AB)\le m$.  Then
\begin{equation}\label{eq:orthog}
 q^{-2m}\sum_{\substack{R\in\mathcal A_{q^2}\\\deg R=m}}
 \chi_R(A)\overline{\chi_R(B)}
 =\begin{cases}
 \displaystyle\frac{\phi_Q(\operatorname{rad}(AB))}{|\operatorname{rad}(AB)|_2},
       &AB^3\text{ is a fourth power},\\[2mm]
 0,&\text{otherwise}.
 \end{cases}
\end{equation}
The radical and Euler function on the right may be evaluated after
factorization over $\mathbb F_{q^2}$.

\label{prop:first-factor}
The contribution of the simple pole at $s=1$ from the diagonal in
\eqref{eq:Aexpand}, evaluated at $w=1/2$, is $q^{2m}\mathcal M_{4,q}(h)$,
where
\begin{equation}\label{eq:Mmain}
 \mathcal M_{4,q}(h)=\frac{c_q}{\sqrt{|h^\ast|}}
 \sum_{B\in\mathcal A_q}\frac{\rho(hB)}{|B|^2}.
\end{equation}
The series converges absolutely and has the Euler product
\begin{align}\label{eq:Mmain-product}
 \mathcal M_{4,q}(h)
 ={}&\frac{c_q\zeta_q(2)}{\sqrt{|h^\ast|}}
 \prod_P\left(1-(1-\rho_P)|P|^{-2}\right)\notag\\
 &\times\prod_{P\mid h}
 \frac{\rho_P}{1-(1-\rho_P)|P|^{-2}}.
\end{align}

\label{lem:root-normalization}
For an admissible $F$ of degree $d\ge1$, with the additive characters
specified in Section~\ref{sec:prelim},
\begin{equation}\label{eq:root-normalization}
 G_q(\chi_F)=\chi_F(F^\sigma)G_Q(1,F)
 =\kappa_q^dG_Q(1,F),\qquad
 \omega(\chi_F)=q^{-d}\kappa_q^dG_Q(1,F).
\end{equation}
Here $G_q(\chi_F)$ has modulus $FF^\sigma$, whereas $G_Q(1,F)$
has modulus $F$.

\label{lem:restricted-gauss}
Let $5/4<\alpha<3/2$ and $|v|=Q^{-\alpha}$. On closed
subintervals of this range, for every $\epsilon>0$,
\begin{equation}\label{eq:needed-gauss}
 \widetilde\Psi_Q(r,v;h)\ll_{q,\epsilon,\alpha}
 |rh|_2^\epsilon |r|_2^{3/4-\alpha/2}.
\end{equation}
The implied constant is uniform in $r,h$ and in the argument of $v$.
The series has a holomorphic continuation throughout
$|v|<Q^{-5/4}$.

\label{input:first}
For every $\varepsilon>0$, uniformly in monic $h$ and integers $m\ge1$,
\begin{align}\label{eq:first-input}
 \sum_{\chi\in\mathcal C_4(g)}\chi(h)L_q(1/2,\chi)
 ={}&q^{2m}\mathcal M_{4,q}(h)\notag\\
 &+O_{q,\varepsilon}\left(q^{(9/5+\varepsilon)m}
            |h^\ast|^{1/10+\varepsilon}|h|^\varepsilon\right),
\end{align}
where $g=3m-3$ and $\mathcal M_{4,q}(h)$ is the absolutely convergent
factor in \eqref{eq:Mmain}--\eqref{eq:Mmain-product}.

\label{rem:first-status}
If $|b(h)|\le1$ and $\deg h\le L$, then
$|h^\ast|\le|h|^3$ and summing the error against
$b(h)|h|^{-1/2}$ gives, after renaming the small exponents,
\[
 q^{(9/5+\varepsilon)m}
 \sum_{n=0}^L q^n q^{(-1/2+3/10+\varepsilon)n}
 \ll_{q,\varepsilon}
 q^{(9/5+\varepsilon)m+(4/5+\varepsilon)L}.
\]
Hence $L<(1/4-\delta)m$, for a fixed $\delta>0$ and sufficiently
small $\varepsilon$, gives a power saving compared with $q^{2m}$.

\label{lem:GZlength}
Writing $M_G(\chi)=\sum_{\deg h\le L}b_m(h)\chi(h)/\sqrt{|h|}$,
one has $|b_m(h)|\le1$ and may take
\begin{equation}\label{eq:GZlength}
 L=2\sum_{r=0}^J\ell_rN_r,
 \qquad \frac Lm\le
 \frac{400\theta_J^{1/4}}{1-e^{-1/4}}+
 \frac{8\theta_J}{1-e^{-1}}<0.000203501.
\end{equation}

\label{lem:GZshort}
Uniformly in $0\le j\le J$, for sufficiently large $m$,
\begin{equation}\label{eq:GZshort}
 \log|L_q(1/2,\chi)|\le
 \operatorname{Re}\sum_{r=0}^j\mathcal P_{r,N_j}(\chi)+\theta_j^{-1}+2.
\end{equation}
At a zero, the left side is interpreted as $-\infty$.

\label{lem:GZTaylor}
Suppose $U=Z_u+Q$, $W=Z_w+Q$, where $Z_u,Z_w$ are prime sums
with coefficient square sums at most $V$, and $|Q|\le D$.
No independence between $Q$ and the prime sums is needed. If
$\ell\ge10^{10}(V+D^2+1)$, then
\begin{equation}\label{eq:GZTaylor}
 \|E_\ell(U/2)E_\ell(-W/2)-e^{(U-W)/2}\|_2\le e^{-\ell}.
\end{equation}
Moreover, if $|z|\le K$ and $\ell\ge100K$, then
\begin{equation}\label{eq:GZpointTaylor}
 E_\ell(\pm z/2)=e^{\pm z/2}(1+\eta),\qquad
 |\eta|\le e^{-2\ell}.
\end{equation}

\label{prop:GZlater}
Put $s_n=\lfloor1/(8\theta_n)\rfloor$ for $n\ge1$. Then
\begin{align}\label{eq:GZbadblock}
 q^{-2m}\sum_{\chi\in\mathcal B_n}|L_q(1/2,\chi)M_G(\chi)|
 \le{}&e^{20}(J-n+1)e^{1/\theta_{n-1}+4(J-n)}
 \left(\frac{16s_n}{K_n^2}\right)^{s_n}.
\end{align}
Consequently
\begin{equation}\label{eq:GZbadlater}
 q^{-2m}\sum_{n=1}^J\sum_{\chi\in\mathcal B_n}|L_q(1/2,\chi)M_G(\chi)|
 \le\frac{e^{20}}{(1-e^{-1})^2}e^{-0.7/\theta_J}.
\end{equation}

\label{lem:GZinitial}
One has
\begin{equation}\label{eq:GZinitial}
 \sum_{\chi\in\mathcal B_0}|L_q(1/2,\chi)M_G(\chi)|=o(q^{2m}).
\end{equation}

\label{prop:GZfirst}
The mollifier \eqref{eq:GZmollifier} satisfies
\begin{equation}\label{eq:GZfirst}
 \sum_{\chi\in\mathcal C_4(g)}L_q(1/2,\chi)M_G(\chi)
 =(c_qA_{4,q,G}+o(1))q^{2m}.
\end{equation}

\label{thm:GZpositive}
For the family \eqref{eq:family},
\begin{equation}\label{eq:GZpositive}
 \displaystyle
 \liminf_{\substack{g\to\infty\\3\mid g}}
 \frac{N_4(g)}{|\mathcal C_4(g)|}
 \ge\frac{A_{4,q,G}}{2 e^{e^{65}+3}}
 \ge\frac1{2 e^{e^{65}+3}}> e^{-e^{66}}.
\end{equation}

\label{sextic:parameterization}
The map $F\mapsto\chi_F$ is a bijection onto the primitive order-six
characters of conductor degree $2m$ satisfying
\begin{equation}\label{sextic:conductor}
 \operatorname{cond}(\chi^2)=\operatorname{cond}(\chi^3)=\operatorname{cond}(\chi).
\end{equation}
These characters are even, their conductor is $FF^\sigma$, and their
completed $L$-polynomial has degree $2m-2$.  The associated cyclic
sextic extension has genus $g=5m-5$.

\label{sextic:restricted-gauss}
The function $\widetilde\Psi_6(r,z;h)$ is holomorphic for
$|z|<Q^{-7/6}$.  Uniformly on closed substrips of $4/3<\beta<3/2$,
\begin{equation}\label{sextic:restricted-bound}
 \widetilde\Psi_6(r,z;h)\ll_{q,\eta}
 |rh|_2^\eta |r|_2^{3/4-\beta/2}
 \qquad(|z|=Q^{-\beta}).
\end{equation}
For $\beta>3/2$, the defining series converges absolutely and is
bounded independently of $r,h$ on closed substrips.

\label{sextic:tfm}
For fixed $q\equiv5\pmod6$ and every $\varepsilon>0$, uniformly in
monic $h$ with $\deg h\le m/10$, one has
\begin{align}\label{sextic:tfm-formula}
 \sum_{F\in\mathcal F_m}\chi_F(h)L_q(1/2,\chi_F)
 ={}&q^{2m}\mathcal M_{6,q}(h)\notag\\
 &+O_{q,\varepsilon}\!\left(q^{(13/7+\varepsilon)m}
                     |h^\ast|^{1/14}|h|^\varepsilon\right),
\end{align}
where
\begin{align}\label{sextic:main}
 \mathcal M_{6,q}(h)
 ={}&\frac{c_q}{\sqrt{|h^\ast|}}
                  \sum_{A\in\mathcal A_q}\frac{\rho(hA)}{|A|^3}\notag\\
 ={}&\frac{c_q\zeta_q(3)}{\sqrt{|h^\ast|}}
  \prod_P\bigl(1-(1-\rho_P)|P|^{-3}\bigr)
  \prod_{P\mid h}\frac{\rho_P}{1-(1-\rho_P)|P|^{-3}}.
\end{align}

\label{sextic:first-moment}
Fix an odd prime power $q\equiv5\pmod6$. For every $\varepsilon>0$,
as $m\to\infty$,
\begin{equation}\label{sextic:first-moment-formula}
 \sum_{F\in\mathcal F_m}L_q(1/2,\chi_F)
 =q^{2m}\mathcal M_{6,q}(1)
  +O_{q,\varepsilon}\!\left(q^{(13/7+\varepsilon)m}\right),
\end{equation}
where
\begin{equation}\label{sextic:first-moment-constant}
 \mathcal M_{6,q}(1)
 =c_q\zeta_q(3)
   \prod_P\left(1-(1-\rho_P)|P|^{-3}\right)>0.
\end{equation}

\label{sextic:twist-length}
Theorem~\ref{sextic:tfm} gives a uniform absolute-error formula; a
relative asymptotic is not asserted for every growing twist in its range.  If $|b(h)|\le1$ and
$\deg h\le L\le m/10$, its summed error is at most
\begin{equation}\label{sextic:summed-error}
 q^{(13/7+\varepsilon)m}
 \sum_{\deg h\le L}|h|^{-1/2}|h^\ast|^{1/14}|h|^\varepsilon
 \ll q^{(13/7+\varepsilon)m+(6/7+\varepsilon)L}.
\end{equation}
The length in \eqref{eq:GZlength} therefore leaves a fixed power
saving relative to $q^{2m}$.

\label{sextic:mollified-first}
For the mollifier \eqref{sextic:blocks},
\begin{equation}\label{sextic:first}
 \sum_{F\in\mathcal F_m}L_q(1/2,\chi_F)M_{6,G}(\chi_F)
 =(c_qA_{6,q,G}+o(1))q^{2m}.
\end{equation}

\label{sextic:positive}
For every fixed $q\equiv5\pmod6$, the family
\eqref{sextic:family} satisfies
\begin{equation}\label{sextic:proportion}
 \liminf_{m\to\infty}\frac{N_6(m)}{N_m}
 \ge\frac{A_{6,q,G}}{2 e^{e^{65}+3}}
 \ge\frac1{2 e^{e^{65}+3}}
 > e^{-e^{66}}.
\end{equation}
Equivalently, this holds for $\mathcal C_6(g)$ as $g\to\infty$
through multiples of five.

\label{cubic:orthog}
If $f,h\in\mathcal A_q$ and $\deg(fh^2)\le m$, then
\begin{equation}\label{cubic:orthog-formula}
 q^{-2m}\sum_{\substack{R\in\mathcal A_{q^2}\\\deg R=m}}
 \chi_R(f)\overline{\chi_R(h)}
 =\begin{cases}
 \displaystyle\frac{\phi_Q(fh)}{|fh|_2},&fh^2\text{ is a cube},\\[2mm]
 0,&\text{otherwise}.
 \end{cases}
\end{equation}
In particular, the identity applies term by term to
$|H(\chi)|^2$, with $H(\chi)=\sum_{\deg f\le D}a(f)\chi(f)$,
whenever $3D\le m$.

\label{cubic:twisted}
For $\deg h<(1/10-\varepsilon)g$,
\begin{align}\label{cubic:twisted-formula}
 \sum_{\chi\in\mathcal C_3(g)}\chi(h)L_q(1/2,\chi)
 ={}&q^{2m}\mathcal M_{3,q}(h)
 +O_{q,\varepsilon}\!\left(q^{7g/8+\deg h/4+\varepsilon g}\right),
 \\
 \mathcal M_{3,q}(h)
 ={}&\frac{c_q}{\sqrt{|h^\ast|}}
       \sum_{A\in\mathcal A_q}\frac{\rho(hA)}{|A|^{3/2}}.
       \label{cubic:moment-constant}
\end{align}

\label{cubic:first}
The mollifier \eqref{cubic:mollifier} satisfies
\begin{equation}\label{cubic:mollified-first}
 \sum_{\chi\in\mathcal C_3(g)}L_q(1/2,\chi)M_{3,G}(\chi)
 =\bigl(c_qA_{3,q,G}+o(1)\bigr)q^{2m}.
\end{equation}

\label{cubic:exceptional}
For every fixed $A>0$,
\begin{align}\label{cubic:exceptional-bound}
 \sum_{\chi\notin\mathcal T^{(3)}}
       |L_q(1/2,\chi)M_{3,G}(\chi)|
 \le{}&q^{2m}\frac{e^{20}}{(1-e^{-1})^2}
                 e^{-\frac{0.7}{\theta_J}}
       +O_{q,A}(q^{2m}m^{-A}).
\end{align}

\label{cubic:positive}
For every fixed odd prime power $q\equiv2\pmod3$,
\begin{equation}\label{cubic:positive-bound}
 \liminf_{\substack{g\to\infty\\2\mid g}}
 \frac{\#\{\chi\in\mathcal C_3(g):L_q(1/2,\chi)\ne0\}}
      {|\mathcal C_3(g)|}
 \ge\frac{A_{3,q,G}}{2 e^{e^{65}+3}}
 \ge\frac1{2 e^{e^{65}+3}}
 > e^{-e^{66}}.
\end{equation}
